// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(0, "", ""); }
    function testFuzz_property(uint256 supply, uint256 burnAmount) public {
        vm.assume(supply > 0);
        vm.assume(burnAmount > 0 && burnAmount <= supply);
        vm.deal(address(this), 0);
        c = new ERCDDAToken(supply, "Token", "TKN");
        uint256 supplyBefore = c.totalSupply();
        vm.prank(address(this));
        c.burn(burnAmount);
        uint256 supplyAfter = c.totalSupply();
        assertTrue(supplyAfter <= supplyBefore);
    }
}
